import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useLocation } from 'react-router-dom';
import styles from '../css/chat.module.css';

const Chat = () => {
  const location = useLocation();
  const { personality, name: chatbotName = '챗봇' } = location.state || {};
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [currentDateTime, setCurrentDateTime] = useState('');
  const [error, setError] = useState(null);
  const [isRecording, setIsRecording] = useState(false); // 음성 인식 상태
  const [isProcessingResponse, setIsProcessingResponse] = useState(false); // 서버 응답 처리 중 상태
  const [audioHtml, setAudioHtml] = useState(null);  // 음성 HTML 상태
  const chatEndRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const audioChunksRef = useRef([]);
  

  const getCurrentDateTime = () => {
    const now = new Date();
    const date = now.toLocaleDateString('ko-KR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long',
    });
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
    return `${date} ${time}`;
  };

  const getTimeOnly = () => {
    const now = new Date();
    return now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
  };

  const handleNewAudioHtml = (newAudioHtml) => {
    // 음성 HTML이 이전과 다를 경우만 처리
    if (audioHtml !== newAudioHtml) {
      setAudioHtml(newAudioHtml);  // 새로운 음성 HTML 설정
    }
  };

  const startRecording = () => {
    if (isRecording || isProcessingResponse) return; // 녹음 중이거나 응답 처리 중이면 동작하지 않음

    console.log('음성 인식 시작');

    // 음성 인식 시작 시 새로운 음성 데이터를 받기 위해 audioChunks 초기화
    audioChunksRef.current = []; // 기존 데이터를 지워서 새로운 음성 데이터만 받도록 한다

    // 일정 시간 동안 음성이 없으면 자동으로 중지
  const silenceTimeout = setTimeout(() => {
    if (isRecording) {
      stopRecording();
      alert("음성이 감지되지 않았습니다. 음성 인식을 중지합니다.");
    }
  }, 5000); // 5초 동안 음성 없으면 자동 중지

  if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
    navigator.mediaDevices.getUserMedia({ audio: true })
      .then((stream) => {
        // 새로운 미디어 레코더를 생성
        mediaRecorderRef.current = new MediaRecorder(stream);

        mediaRecorderRef.current.ondataavailable = (event) => {
          console.log('ondataavailable: audio data available');
          audioChunksRef.current.push(event.data); // 음성 데이터 저장
        };

        mediaRecorderRef.current.onstop = async () => {
          clearTimeout(silenceTimeout); // 녹음이 멈추면 타이머 제거
          console.log('녹음 중지');
          const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/mp3' });
          const audioData = await audioBlob.arrayBuffer();
          const formData = new FormData();
          formData.set('chatbot_name', chatbotName);
          formData.set('personality', personality);
          formData.set('file', new Blob([audioData]), 'audio.mp3');

          try {
            setIsProcessingResponse(true); // 응답 처리 중 상태로 설정
            console.log('파일 전송 중...');
            const response = await fetch(`${process.env.REACT_APP_API_URL}/chat-audio`, {
              method: 'POST',
              body: formData,
            });
            if (!response.ok) {
              throw new Error("음성 파일 전송 오류");
            }
            const data = await response.json();
            const chatbotMessage = data.response;
            const newAudioHtml = data.audio_html;
            const recognizedText = data.transcribed_text;

            const sentTime = getTimeOnly();
            setChatHistory(prevHistory => [
              ...prevHistory,
              { sender: "사용자", message: recognizedText, time: sentTime }
            ]);

            const receivedTime = getTimeOnly();
            setChatHistory(prevHistory => [
              ...prevHistory,
              { sender: chatbotName, message: chatbotMessage, time: receivedTime }
            ]);

            handleNewAudioHtml(newAudioHtml);  // 새로운 음성 HTML 처리
            setUserInput(""); // 음성 인식 후 입력 초기화
          } catch (error) {
            setError(error.message);
          } finally {
            setIsProcessingResponse(false); // 응답 처리 완료 후 상태 변경
            console.log('파일 전송 완료');
          }
        };

        mediaRecorderRef.current.start();
        setIsRecording(true); // 음성 인식 시작
      })
      .catch((err) => {
        console.error("녹음 권한을 요청할 수 없습니다.", err);
        console.log("음성 인식 실패:", err);
      });
    }
  };

  const stopRecording = () => {
    if (!isRecording) return; // 녹음 중이 아닐 때는 동작하지 않도록 방지

    console.log('음성 인식 중지');

    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
    }
    setIsRecording(false); // 녹음 종료 후 상태 변경

    // 녹음이 중지되면 audioChunks를 비워줘서 새로운 데이터를 받을 준비가 되도록 한다
    audioChunksRef.current = [];  // 반드시 초기화
    setAudioHtml(null);  // 새로운 음성 HTML 처리 전 이전 HTML 초기화
  };

  const handleSendMessage = async () => {
    if (isRecording || isProcessingResponse || userInput.trim() === "") return; // 음성 인식 중이거나 서버 응답 처리 중일 때 전송 방지

    const sentTime = getTimeOnly();
    const newMessage = { sender: "사용자", message: userInput, time: sentTime };
    setChatHistory((prevHistory) => [...prevHistory, newMessage]);
    setUserInput("");

    try {
      setIsProcessingResponse(true); // 응답 처리 중 상태로 설정
      console.log('서버에 메시지 전송 중...');
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chatbotName: chatbotName,
          user_input: userInput,
          personality: personality,
        }),
      });
      if (!response.ok) {
        throw new Error("서버 응답 오류");
      }
      const data = await response.json();
      const chatbotMessage = data.response;
      const newAudioHtml = data.audio_html;

      const receivedTime = getTimeOnly();
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: chatbotName, message: chatbotMessage, time: receivedTime },
      ]);
      handleNewAudioHtml(newAudioHtml);  // 새로운 음성 HTML 처리
    } catch (error) {
      setError(error.message);
    } finally {
      setIsProcessingResponse(false); // 응답 처리 완료 후 상태 변경
      console.log('서버 응답 완료');
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleSendMessage();
    }
  };

  const displayErrorMessage = useCallback(() => {
    return error ? <div className={styles.errorMessage}>{error}</div> : null;
  }, [error]);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentDateTime(getCurrentDateTime());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [chatHistory]);

  return (
    <div className={styles.chatContainer}>
      <div className={styles.chatDataTime}>
        <strong>{currentDateTime}</strong>
      </div>
      <div className={styles.chatHistory}>
        {chatHistory.map((chat, index) => (
          <div key={index} className={chat.sender === '사용자' ? styles.chatMessageUser : styles.chatMessageChatbot}>
            <strong>{chat.sender === "사용자" ? "사용자" : chatbotName}:</strong>
            <div>{chat.message}</div>
            <div className={chat.sender === '사용자' ? styles.chatTimeUser : styles.chatTimeChatbot}>
              <em>{chat.time}</em>
            </div>
          </div>
        ))}
        <div ref={chatEndRef} />
      </div>
      <div className={styles.chatInputArea}>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={handleKeyDown}
          disabled={isRecording || isProcessingResponse}  // 음성 인식 중이나 응답 처리 중에는 텍스트 입력 비활성화
        />
        <button className={styles.chatSendButton} onClick={handleSendMessage} disabled={isRecording || isProcessingResponse}>전송</button>
        <button className={styles.voiceButton} onClick={isRecording ? stopRecording : startRecording}>
          {isRecording ? "녹음 중지" : "음성 인식 시작"}
        </button>
      </div>
      {displayErrorMessage()}
      {!isRecording && audioHtml && <div dangerouslySetInnerHTML={{ __html: audioHtml }} />}
    </div>
  );
};

export default Chat;
